{
  "name": "CPSubsystemConfig",
  "package": "hazelcast",
  "description": "CPSubsystemConfig configures the consensus-based strong consistency subsystem.\n Used for distributed locks, atomic counters, and leader election.\n Requires an odd number of members (minimum 3) for Raft quorum.",
  "fields": [
    {
      "name": "enabled",
      "type": "bool",
      "description": "enabled controls whether the CP subsystem is active.\n Must be enabled for distributed locks (Lock service) to work."
    },
    {
      "name": "cp_member_count",
      "type": "int32",
      "description": "cp_member_count is the number of cluster members that participate in\n the CP (consensus protocol) group. Must be odd and \u003e= 3.\n Only these members vote in Raft elections; others are observers.",
      "default": 3,
      "constraints": [
        "must be \u003e= 3"
      ]
    },
    {
      "name": "session_timeout_seconds",
      "type": "int64",
      "description": "session_timeout_seconds is the maximum time a CP session can be inactive\n before it is closed and its resources (locks, etc.) are released.",
      "default": 300,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ]
    },
    {
      "name": "session_heartbeat_interval_seconds",
      "type": "int64",
      "description": "session_heartbeat_interval_seconds is the interval for CP session heartbeats.\n Must be less than session_timeout_seconds.",
      "default": 5,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ]
    },
    {
      "name": "missing_cp_member_auto_removal_seconds",
      "type": "int64",
      "description": "missing_cp_member_auto_removal_seconds is how long to wait before automatically\n removing a missing CP member from the group. Set to 0 to disable auto-removal.",
      "default": 14400,
      "constraints": [
        "duration constraint: DURATION_TYPE_NON_NEGATIVE"
      ]
    }
  ]
}

