      "name": "error_message",
      "type": "string",
      "description": "error_message is the error text if the tool call failed.",
      "constraints": [
        "maximum length: 4096"
      ]
    },
    {
      "name": "file_events",
      "type": "message",
      "description": "file_events are file operations performed by this tool call.\n Populated for Write, Edit, Bash (when file side-effects detected).",
      "repeated": true,
      "message": {
        "name": "FileEvent",
        "package": "sensor",
        "description": "FileEvent captures a file operation.",
        "fields": [
          {
            "name": "file_path",
            "type": "string",
            "description": "file_path is the absolute path of the affected file.",
            "required": true,
            "constraints": [
              "maximum length: 4096"
            ]
          },
          {
            "name": "operation",
            "type": "enum",
            "description": "operation is what happened to the file.",
