                "name": "FILE_OPERATION_CREATE",
                "number": 1
              },
              {
                "name": "FILE_OPERATION_MODIFY",
                "number": 2
              },
              {
                "name": "FILE_OPERATION_DELETE",
                "number": 3
              },
              {
                "name": "FILE_OPERATION_READ",
                "number": 4
              }
            ]
          },
          {
            "name": "language",
            "type": "string",
            "description": "language is the detected language from the file extension (e.g. \"go\", \"rust\", \"proto\").",
            "constraints": [
              "maximum length: 64"
            ]
          },
          {
            "name": "size_bytes",
            "type": "int64",
            "description": "size_bytes is the file size after the operation.",
            "constraints": [
              "must be \u003e= 0"
            ]
          },
          {
            "name": "lines_changed",
            "type": "int32",
            "description": "lines_changed is the number of lines added or modified.",
            "constraints": [
              "must be \u003e= 0"
            ]
          },
          {
            "name": "is_new_file",
            "type": "bool",
            "description": "is_new_file is true when a file is created for the first time."
          },
          {
            "name": "is_generated",
            "type": "bool",
            "description": "is_generated is true when the file was written by a subagent (not the root agent)."
          }
        ]
      }
    },
    {
      "name": "tool_use_id",
      "type": "string",
      "description": "tool_use_id is the unique ID for this tool invocation.\n Correlates PreToolUse with its PostToolUse for the same call.",
      "constraints": [
        "maximum length: 128"
      ]
    }
  ]
}

