{
  "name": "TokenMintRequest",
  "package": "tokenrequest",
  "description": "TokenMintRequest is the unified input for the TokenMint RPC.\n Covers both direct exchange (caller presents credentials) and delegation\n (broker mints on behalf of another principal).\n\n Direct exchange: input_token or cloud_proof authenticates the caller.\n   Subject is derived from the credentials. Profiles are resolved from\n   the Delegate's authorized_profiles.\n\n Delegation: caller authenticates via header (service token). Subject,\n   profiles, and claims are specified explicitly. Kernel verifies the\n   caller is authorized to delegate.",
  "fields": [
    {
      "name": "input_token",
      "type": "string",
      "description": "input_token is a JWT to validate (delegate cred_pair JWT or refresh token)."
    },
    {
      "name": "cloud_proof",
      "type": "message",
      "description": "cloud_proof is a cloud-native identity proof (AWS STS, GCP, Azure).\n Used instead of input_token for cloud-native auth.",
      "message": {
        "name": "CloudIdentityProof",
        "package": "cloudidentity",
        "description": "CloudIdentityProof carries a cloud-native identity assertion.\n Exactly one of presigned_request or identity_token must be set,\n determined by the cloud vendor.",
        "fields": [
          {
            "name": "vendor",
            "type": "enum",
            "description": "vendor identifies the cloud provider that issued this proof.",
            "enum_values": [
              {
                "name": "CLOUD_VENDOR_AWS",
                "number": 1,
                "description": "Amazon Web Services (AWS)"
              },
              {
                "name": "CLOUD_VENDOR_AZURE",
                "number": 2,
                "description": "Microsoft Azure"
              },
              {
                "name": "CLOUD_VENDOR_GCP",
                "number": 3,
                "description": "Google Cloud Platform (GCP)"
              },
              {
                "name": "CLOUD_VENDOR_ORACLE",
                "number": 4,
                "description": "Oracle Cloud"
              },
              {
                "name": "CLOUD_VENDOR_ALIBABA",
                "number": 5,
                "description": "Alibaba Cloud"
              },
              {
                "name": "CLOUD_VENDOR_IBM",
                "number": 6,
                "description": "IBM Cloud"
              }
            ]
          },
          {
            "name": "presigned_request",
            "type": "message",
            "description": "presigned_request is used for AWS: a signed STS GetCallerIdentity\n request that the server executes to verify the caller's IAM identity.\n The request has a short TTL to prevent replay.",
            "message": {
              "name": "PresignedHttpRequest",
              "package": "cloudidentity",
              "description": "PresignedHttpRequest carries a pre-signed HTTP request that the server\n executes on behalf of the caller. For AWS, this is a SigV4-signed\n STS GetCallerIdentity request.",
              "fields": [
                {
                  "name": "method",
                  "type": "string",
                  "description": "method is the HTTP method (e.g. \"POST\").",
                  "required": true,
                  "constraints": [
                    "maximum length: 16"
                  ]
                },
                {
                  "name": "url",
                  "type": "string",
                  "description": "url is the full request URL including query parameters.",
                  "required": true,
                  "constraints": [
                    "maximum length: 2048"
                  ]
                },
                {
                  "name": "headers",
                  "type": "map",
                  "description": "headers are the signed HTTP headers that must be forwarded verbatim.\n Keys are header names, values are header values.",
                  "repeated": true,
                  "map_key_type": "string",
                  "map_value_type": "string"
                },
                {
                  "name": "body",
                  "type": "string",
                  "description": "body is the request body (e.g. \"Action=GetCallerIdentity\u0026Version=2011-06-15\")."
                }
              ]
            }
          },
          {
            "name": "identity_token",
            "type": "string",
            "description": "identity_token is used for GCP and Azure: a signed JWT or OAuth2\n token obtained from the cloud metadata service. The server validates\n it against the provider's public JWKS/OIDC endpoint."
          }
        ]
      }
    },
    {
      "name": "continuity_token",
      "type": "string",
      "description": "continuity_token is a non-expired refresh token proving instance continuity\n across restarts. Optional."
    },
    {
      "name": "aud",
      "type": "string",
      "description": "aud is the target service for the issued token.",
      "constraints": [
        "minimum length: 1",
        "maximum length: 256"
      ]
    },
    {
      "name": "exp",
      "type": "int64",
      "description": "exp is the desired expiry epoch (optional; 0 = use default, capped by server policy).",
      "constraints": [
        "must be \u003e= 0"
      ]
    },
    {
      "name": "token_purpose",
      "type": "enum",
      "description": "token_purpose selects refresh or access token semantics.",
      "enum_values": [
        {
          "name": "TOKEN_PURPOSE_REFRESH",
          "number": 1,
          "description": "Refresh token — long-lived, used to obtain new access tokens."
        },
        {
          "name": "TOKEN_PURPOSE_ACCESS",
          "number": 2,
          "description": "Access token — short-lived, carries entitlements for a specific service."
        }
      ]
    },
    {
      "name": "subject",
      "type": "string",
      "description": "subject is the token's sub claim. Empty = derive from credentials.\n Brokers set this explicitly when minting on behalf of another principal.",
      "constraints": [
        "maximum length: 256"
      ]
    },
    {
      "name": "claims",
      "type": "message",
      "description": "claims are custom claims to embed in the token (e.g., origin IDP claims,\n auth_type, azp). Standard JWT claims (sub, iss, aud, exp, iat, jti) are\n set by kernel and must not appear here."
    },
    {
      "name": "profiles",
      "type": "string",
      "description": "profiles are identity profile names to resolve into entitlements.\n Kernel resolves each profile via identity_profiles config to get concrete\n per-service RPC lists for the target service (aud).",
      "repeated": true
    }
  ]
}

{
  "name": "TokenMintResponse",
  "package": "tokenrequest",
  "description": "TokenMintResponse is the response from the TokenMint RPC.\n Always contains an access token. On initial exchange (cred_pair or cloud\n bootstrap), also contains a refresh token so callers get both in one call.",
  "fields": [
    {
      "name": "access_token",
      "type": "message",
      "description": "access_token is the primary token — a signed JWT for the requested audience.",
      "message": {
        "name": "Token",
        "package": "token",
        "description": "Token represents a JWT (JSON Web Token) with header, payload, and signature components.\n The token can be in either parsed form (header/payload maps) or encoded form (base64 string).",
        "fields": [
          {
            "name": "header",
            "type": "map",
            "description": "Header contains the JWT header claims (e.g., alg, typ, kid)",
            "repeated": true,
            "map_key_type": "string",
            "map_value_type": "string"
          },
          {
            "name": "payload",
            "type": "map",
            "description": "JWT payload claims stored as string values. Numeric claims (exp, iat, nbf)\n are stored as decimal string representations (e.g., \"1742403600\").",
            "repeated": true,
            "map_key_type": "string",
            "map_value_type": "string"
          },
          {
            "name": "signature",
            "type": "string",
            "description": "Signature is the base64url-encoded signature",
            "constraints": [
              "must be base64 encoded"
            ]
          },
          {
            "name": "base64",
            "type": "string",
            "description": "Base64 contains the complete JWT in base64url format (header.payload.signature)",
            "constraints": [
              "must be base64 encoded"
            ]
          }
        ]
      }
    },
    {
      "name": "refresh_token",
      "type": "message (recursive reference: token.Token)",
      "description": "refresh_token is only populated on initial exchange (bootstrap).\n Callers cache it and use it to obtain new access tokens later."
    }
  ]
}

{
  "name": "X509MintRequest",
  "package": "tokenrequest",
  "description": "X509MintRequest is the input for the X509Mint RPC.\n Authentication comes from the caller's bearer token — either in the\n Authorization header or in the input_token field (for gateway-mediated\n calls). The token's sub claim identifies the service; kernel creates a\n per-service intermediate CA and signs the certificate under it.",
  "fields": [
    {
      "name": "aud",
      "type": "string",
      "description": "aud is the intended audience / service name for the certificate.",
      "constraints": [
        "minimum length: 1",
        "maximum length: 256"
      ]
    },
    {
      "name": "cert_request",
      "type": "message",
      "description": "cert_request contains the public key, expiry, key usage, and other\n X.509 certificate parameters. The caller provides its public key;\n kernel signs it under the service's intermediate CA.",
      "required": true,
      "message": {
        "name": "X509CertRequest",
        "package": "x509",
        "description": "X509CertRequest represents a certificate signing request (CSR) for generating X.509 certificates.\n It contains the public key to be certified, validity period, key usage constraints,\n and issuer information needed to create a signed certificate.",
        "fields": [
          {
            "name": "key",
            "type": "message",
            "description": "Key is the public key to be certified",
            "message": {
              "name": "PublicKey",
              "package": "key",
              "description": "PublicKey represents a public cryptographic key.\n The key is stored as a base64-encoded PEM block in PKIX format.\n Use NewProtoPublicKey() in Go or similar constructors in other languages to create.",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the key (corresponds to kid in JWK)",
                  "required": true,
                  "constraints": [
                    "minimum length: 1"
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM public key block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded"
                  ]
                },
                {
                  "name": "created",
                  "type": "int64",
                  "description": "Created is the Unix epoch timestamp (seconds) when the key was created\n Valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                  "required": true,
                  "constraints": [
                    "must be \u003e= 1735689600",
                    "must be \u003c= 8045740800"
                  ]
                }
              ]
            }
          },
          {
            "name": "exp",
            "type": "int64",
            "description": "Exp is the expiration timestamp (Unix time) for the certificate",
            "required": true,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ]
          },
          {
            "name": "metadata",
            "type": "message",
            "description": "Metadata contains additional information about the certificate request"
          },
          {
            "name": "key_usage",
            "type": "enum",
            "description": "KeyUsage specifies the intended cryptographic operations (e.g., \"digitalSignature\", \"keyEncipherment\")",
            "required": true,
            "enum_values": [
              {
                "name": "X509_KEY_USAGE_DIGITAL_SIGNATURE",
                "number": 0,
                "description": "X509KeyUsageDigitalSignature indicates digital signature usage"
              },
              {
                "name": "X509_KEY_USAGE_CONTENT_COMMITMENT",
                "number": 1,
                "description": "X509KeyUsageContentCommitment indicates content commitment (non-repudiation)"
              },
              {
                "name": "X509_KEY_USAGE_KEY_ENCIPHERMENT",
                "number": 2,
                "description": "X509KeyUsageKeyEncipherment indicates key encipherment"
              },
              {
                "name": "X509_KEY_USAGE_DATA_ENCIPHERMENT",
                "number": 3,
                "description": "X509KeyUsageDataEncipherment indicates data encipherment"
              },
              {
                "name": "X509_KEY_USAGE_KEY_AGREEMENT",
                "number": 4,
                "description": "X509KeyUsageKeyAgreement indicates key agreement"
              },
              {
                "name": "X509_KEY_USAGE_CERT_SIGN",
                "number": 5,
                "description": "X509KeyUsageCertSign indicates certificate signing"
              },
              {
                "name": "X509_KEY_USAGE_CRL_SIGN",
                "number": 6,
                "description": "X509KeyUsageCRLSign indicates CRL signing"
              },
              {
                "name": "X509_KEY_USAGE_ENCIPHER_ONLY",
                "number": 7,
                "description": "X509KeyUsageEncipherOnly indicates encipher only"
              },
              {
                "name": "X509_KEY_USAGE_DECIPHER_ONLY",
                "number": 8,
                "description": "X509KeyUsageDecipherOnly indicates decipher only"
              }
            ]
          },
          {
            "name": "ext_key_usage",
            "type": "enum",
            "description": "ExtKeyUsage specifies extended key usage purposes for the certificate",
            "repeated": true,
            "enum_values": [
              {
                "name": "X509_EXT_KEY_USAGE_ANY",
                "number": 0,
                "description": "X509ExtKeyUsageAny indicates any extended key usage"
              },
              {
                "name": "X509_EXT_KEY_USAGE_SERVER_AUTH",
                "number": 1,
                "description": "X509ExtKeyUsageServerAuth indicates TLS server authentication"
              },
              {
                "name": "X509_EXT_KEY_USAGE_CLIENT_AUTH",
                "number": 2,
                "description": "X509ExtKeyUsageClientAuth indicates TLS client authentication"
              },
              {
                "name": "X509_EXT_KEY_USAGE_CODE_SIGNING",
                "number": 3,
                "description": "X509ExtKeyUsageCodeSigning indicates code signing"
              },
              {
                "name": "X509_EXT_KEY_USAGE_EMAIL_PROTECTION",
                "number": 4,
                "description": "X509ExtKeyUsageEmailProtection indicates email protection (S/MIME)"
              },
              {
                "name": "X509_EXT_KEY_USAGE_IPSEC_END_SYSTEM",
                "number": 5,
                "description": "X509ExtKeyUsageIPSECEndSystem indicates IPSEC end system"
              },
              {
                "name": "X509_EXT_KEY_USAGE_IPSEC_TUNNEL",
                "number": 6,
                "description": "X509ExtKeyUsageIPSECTunnel indicates IPSEC tunnel"
              },
              {
                "name": "X509_EXT_KEY_USAGE_IPSEC_USER",
                "number": 7,
                "description": "X509ExtKeyUsageIPSECUser indicates IPSEC user"
              },
              {
                "name": "X509_EXT_KEY_USAGE_TIME_STAMPING",
                "number": 8,
                "description": "X509ExtKeyUsageTimeStamping indicates time stamping"
              },
              {
                "name": "X509_EXT_KEY_USAGE_OCSP_SIGNING",
                "number": 9,
                "description": "X509ExtKeyUsageOCSPSigning indicates OCSP signing"
              },
              {
                "name": "X509_EXT_KEY_USAGE_MICROSOFT_SERVER_GATED_CRYPTO",
                "number": 10,
                "description": "X509ExtKeyUsageMicrosoftServerGatedCrypto indicates Microsoft Server Gated Crypto"
              },
              {
                "name": "X509_EXT_KEY_USAGE_NETSCAPE_SERVER_GATED_CRYPTO",
                "number": 11,
                "description": "X509ExtKeyUsageNetscapeServerGatedCrypto indicates Netscape Server Gated Crypto"
              },
              {
                "name": "X509_EXT_KEY_USAGE_MICROSOFT_COMMERCIAL_CODE_SIGNING",
                "number": 12,
                "description": "X509ExtKeyUsageMicrosoftCommercialCodeSigning indicates Microsoft Commercial Code Signing"
              },
              {
                "name": "X509_EXT_KEY_USAGE_MICROSOFT_KERNEL_CODE_SIGNING",
                "number": 13,
                "description": "X509ExtKeyUsageMicrosoftKernelCodeSigning indicates Microsoft Kernel Code Signing"
              }
            ]
          },
          {
            "name": "issuer",
            "type": "string",
            "description": "Issuer is the distinguished name (DN) of the certificate issuer",
            "required": true,
            "constraints": [
              "minimum length: 1"
            ]
          },
          {
            "name": "is_ca",
            "type": "bool",
            "description": "is_ca marks this as a CA certificate (adds BasicConstraints CA:TRUE)."
          },
          {
            "name": "path_len_constraint",
            "type": "int32",
            "description": "path_len_constraint limits CA signing depth (-1 = unlimited, 0 = leaf-only).\n Only meaningful when is_ca is true."
          },
          {
            "name": "dns_names",
            "type": "string",
            "description": "dns_names adds Subject Alternative Name DNS entries to the certificate.",
            "repeated": true
          },
          {
            "name": "uri_sans",
            "type": "string",
            "description": "uri_sans adds Subject Alternative Name URI entries (e.g. SPIFFE IDs).",
            "repeated": true
          }
        ]
      }
    },
    {
      "name": "input_token",
      "type": "string",
      "description": "input_token is the caller's service token (JWT). When gateway mediates\n the X509Mint call, the token is passed in the request body instead of\n the Authorization header. Matches TokenMintRequest's pattern."
    }
  ]
}

