{
  "name": "BigDataAnnotation",
  "package": "spec",
  "description": "BigDataAnnotation opts a proto message into the BigData multi-store platform.\n The generator scans field-level annotations (cache, timeseries, graph_index,\n archive) to determine which stores each field is projected into.\n Fields with no store annotation live only in the source of truth chain\n (HZ → Cassandra → Iceberg).",
  "fields": [
    {
      "name": "name",
      "type": "string",
      "description": "name is the BigData type name (e.g. \"Entity\", \"Host\")."
    },
    {
      "name": "key",
      "type": "string",
      "description": "key is the proto field name used as the unique identifier across all stores."
    }
  ]
}

{
  "name": "BoolConst",
  "package": "spec",
  "description": "File-level bool constants.\n BoolConst defines a named boolean constant that can be used in file-level options.",
  "fields": [
    {
      "name": "name",
      "type": "string",
      "description": "Name is the identifier for the constant"
    },
    {
      "name": "value",
      "type": "bool",
      "description": "Value is the boolean value of the constant"
    }
  ]
}

{
  "name": "ConditionalRequirement",
  "package": "spec",
  "description": "ConditionalRequirement defines a conditional requirement for a field.\n The field is required when a sibling field equals a specific value.",
  "fields": [
    {
      "name": "field",
      "type": "string",
      "description": "field is the sibling field name (snake_case) to check"
    },
    {
      "name": "value",
      "type": "string",
      "description": "value is the enum value name or string to compare against"
    }
  ]
}

{
  "name": "DefaultHost",
  "package": "spec",
  "description": "DefaultHost provides default values for host.Host fields.\n Mirrors host.Host structure to avoid circular import with host.proto.",
  "fields": [
    {
      "name": "host",
      "type": "string"
    },
    {
      "name": "port",
      "type": "int32"
    }
  ]
}

{
  "name": "FloatConst",
  "package": "spec",
  "description": "File-level float constants.\n FloatConst defines a named floating-point constant that can be used in file-level options.",
  "fields": [
    {
      "name": "name",
      "type": "string",
      "description": "Name is the identifier for the constant"
    },
    {
      "name": "value",
      "type": "double",
      "description": "Value is the floating-point value of the constant"
    }
  ]
}

{
  "name": "FloatConstraint",
  "package": "spec",
  "description": "FloatConstraint defines constraints for floating-point fields (float, double)",
  "fields": [
    {
      "name": "gt",
      "type": "double",
      "description": "gt: field must be greater than this value"
    },
    {
      "name": "ge",
      "type": "double",
      "description": "ge: field must be greater than or equal to this value"
    },
    {
      "name": "lt",
      "type": "double",
      "description": "lt: field must be less than this value"
    },
    {
      "name": "le",
      "type": "double",
      "description": "le: field must be less than or equal to this value"
    },
    {
      "name": "epsilon",
      "type": "double",
      "description": "epsilon: tolerance for floating-point equality comparisons (default: 1e-9)\n Used when comparing floats to avoid precision issues"
    },
    {
      "name": "in",
      "type": "double",
      "description": "in: field must be one of these values (within epsilon)",
      "repeated": true
    },
    {
      "name": "not_in",
      "type": "double",
      "description": "not_in: field must not be one of these values (within epsilon)",
      "repeated": true
    }
  ]
}

{
  "name": "GrpcConfigAnnotation",
  "package": "spec",
  "description": "GrpcConfigAnnotation marks a message as a gRPC service's configuration.\n tacplus uses these to auto-generate a generated.Services message that aggregates all\n gRPC configs, plus per-service config state boundaries.",
  "fields": [
    {
      "name": "service_name",
      "type": "string",
      "description": "service_name is the gRPC service name.\n Deprecated: prefer file-level option (spec.service). Kept for compatibility."
    },
    {
      "name": "id",
      "type": "int32",
      "description": "id is the stable field number for this config in the generated.Services message.\n When omitted, tacplus may reuse the file-level service id."
    }
  ]
}

{
  "name": "IntConst",
  "package": "spec",
  "description": "File-level int constants.\n IntConst defines a named integer constant that can be used in file-level options.",
  "fields": [
    {
      "name": "name",
      "type": "string",
      "description": "Name is the identifier for the constant"
    },
    {
      "name": "value",
      "type": "int64",
      "description": "Value is the integer value of the constant"
    }
  ]
}

{
  "name": "NumericConstraint",
  "package": "spec",
  "description": "NumericConstraint defines constraints for integer fields (int32, int64, uint32, uint64)\n This message supports complex validation scenarios beyond simple comparisons",
  "fields": [
    {
      "name": "gt",
      "type": "int64",
      "description": "gt: field must be greater than this value"
    },
    {
      "name": "ge",
      "type": "int64",
      "description": "ge: field must be greater than or equal to this value"
    },
    {
      "name": "lt",
      "type": "int64",
      "description": "lt: field must be less than this value"
    },
    {
      "name": "le",
      "type": "int64",
      "description": "le: field must be less than or equal to this value"
    },
    {
      "name": "eq",
      "type": "int64",
      "description": "eq: field must equal this value"
    },
    {
      "name": "ne",
      "type": "int64",
      "description": "ne: field must not equal this value"
    },
    {
      "name": "in",
      "type": "int64",
      "description": "in: field must be one of these values",
      "repeated": true
    },
    {
      "name": "not_in",
      "type": "int64",
      "description": "not_in: field must not be one of these values",
      "repeated": true
    },
    {
      "name": "multiple_of",
      "type": "int64",
      "description": "multiple_of: field must be divisible by this value (field % multiple_of == 0)"
    }
  ]
}

{
  "name": "ParamMapConfig",
  "package": "spec",
  "description": "ParamMapConfig configures automatic generation of FromMap methods\n This generates a method that converts a map[string]string to the message type,\n where the map keys correspond to enum values with json_return_value annotations",
  "fields": [
    {
      "name": "key_enum",
      "type": "string",
      "description": "The enum type to use for parameter keys (e.g., \"TokenParamKey\")\n The enum must have json_return_value annotations on its values"
    },
    {
      "name": "strict",
      "type": "bool",
      "description": "Whether to return an error on unknown keys (default: false, ignore unknown)"
    },
    {
      "name": "validate_required",
      "type": "bool",
      "description": "Whether to return an error if required fields are missing (default: true)"
    }
  ]
}

{
  "name": "QueriesAnnotation",
  "package": "spec",
  "description": "QueriesAnnotation marks a message as a query interface for a BigData type.\n Each string field within the annotated message defines a named query using\n the (spec.sql) field annotation. The generator parses the SQL and compiles\n it into a DAG of store-specific operations.",
  "fields": [
    {
      "name": "target",
      "type": "string",
      "description": "target is the BigData type name this query interface operates on."
    }
  ]
}

{
  "name": "RestMethods",
  "package": "spec",
  "description": "RestMethods is a wrapper for repeated RestMethod, used in method options.",
  "fields": [
    {
      "name": "methods",
      "type": "enum",
      "repeated": true,
      "enum_values": [
        {
          "name": "REST_METHOD_GET",
          "number": 1
        },
        {
          "name": "REST_METHOD_PATCH",
          "number": 2
        },
        {
          "name": "REST_METHOD_PUT",
          "number": 3
        },
        {
          "name": "REST_METHOD_DELETE",
          "number": 4
        }
      ]
    }
  ]
}

{
  "name": "ServiceAnnotation",
  "package": "spec",
  "description": "ServiceAnnotation declares the owning service identity for a proto file.",
  "fields": [
    {
      "name": "name",
      "type": "string",
      "description": "name is the canonical service name (e.g. \"kernel\", \"identity\")."
    },
    {
      "name": "id",
      "type": "int32",
      "description": "id is the stable numeric identifier for this service in the generated tacplus service schema."
    },
    {
      "name": "store",
      "type": "bool",
      "description": "store declares this service as a backing store.\n Other services reference it via StateAnnotation.store."
    },
    {
      "name": "gateway",
      "type": "bool",
      "description": "gateway declares this service as a gateway (reverse proxy).\n Changes TLS source to GatewayTlsState (public cert) instead of X509Mint (internal CA).\n The generated run() watches GatewayTlsState for cert hot-reload instead of running\n a TLS renewal loop."
    }
  ]
}

{
  "name": "ServiceEventAnnotation",
  "package": "spec",
  "description": "ServiceEventAnnotation declares that a state service's topic/queue RPCs\n are accessible to other services (S2S only, like service_state).\n Services declare access via tacplus.yaml states: entries with :ro/:rw.",
  "fields": [
    {
      "name": "tag",
      "type": "string",
      "description": "tag is the routing label for service resolution (e.g. \"eventbus\")."
    }
  ]
}

{
  "name": "ServiceGrpcAnnotation",
  "package": "spec",
  "description": "ServiceGrpcAnnotation declares a gRPC service with its auth policy.\n Auth fields are combinable: a service can accept services AND entitled users.\n Gateway exposure is derived: auth_entitled_users || auth_any_user → gateway.",
  "fields": [
    {
      "name": "name",
      "type": "string",
      "description": "name is the service identity used in routing and config (e.g. \"sentinel\")."
    },
    {
      "name": "auth_disabled",
      "type": "bool",
      "description": "auth_disabled: no token required, anyone can call."
    },
    {
      "name": "auth_services",
      "type": "string",
      "description": "auth_services: authenticated service identities allowed to call.\n [\"*\"] = any service. Named entries restrict to those identities.",
      "repeated": true
    },
    {
      "name": "auth_entitled_users",
      "type": "bool",
      "description": "auth_entitled_users: users with auto-determined entitlements can call."
    },
    {
      "name": "auth_any_user",
      "type": "bool",
      "description": "auth_any_user: any authenticated user can call (no entitlement check)."
    }
  ]
}

{
  "name": "StateAnnotation",
  "package": "spec",
  "description": "StateAnnotation marks a message as a state root and references its backing store.",
  "fields": [
    {
      "name": "name",
      "type": "string",
      "description": "name is the state root name (e.g. \"ClusterState\", \"AegisState\")."
    },
    {
      "name": "store",
      "type": "string",
      "description": "store is the backing service name (must match a spec.service with store=true).\n Deprecated: use tag instead."
    },
    {
      "name": "tag",
      "type": "string",
      "description": "tag is the routing label for the backing store (e.g. \"kernel\", \"eventbus\")."
    },
    {
      "name": "auto_tls",
