          "name": "STATE_PERMS_MODE_RW",
          "number": 2,
          "description": "STATE_PERMS_MODE_RW grants full read-write access (get, set, lock, delete)."
        },
        {
          "name": "STATE_PERMS_MODE_WORM",
          "number": 3,
          "description": "STATE_PERMS_MODE_WORM grants write-once read-many access (get, set, add, publish, offer — no lock/delete)."
