{
  "name": "ProxyEvent",
  "package": "gitlab",
  "description": "ProxyEvent captures a single proxied GitLab API request/response pair.\n Emitted as a typed event for every API call, whether through a typed\n RPC or the generic proxy fallback.",
  "fields": [
    {
      "name": "subject",
      "type": "string",
      "description": "Identity of the caller (sub claim from the bearer token).",
      "required": true,
      "constraints": [
        "minimum length: 1",
        "maximum length: 256"
      ]
    },
    {
      "name": "method",
      "type": "enum",
      "description": "HTTP method of the proxied request.",
      "enum_values": [
        {
          "name": "HTTP_METHOD_GET",
          "number": 1
        },
        {
          "name": "HTTP_METHOD_POST",
          "number": 2
        },
        {
          "name": "HTTP_METHOD_PUT",
          "number": 3
        },
        {
          "name": "HTTP_METHOD_PATCH",
          "number": 4
        },
        {
          "name": "HTTP_METHOD_DELETE",
          "number": 5
        },
        {
          "name": "HTTP_METHOD_HEAD",
          "number": 6
        }
      ]
    },
    {
      "name": "path",
      "type": "string",
      "description": "API path of the proxied request (e.g., \"/api/v4/projects/123/issues\").",
      "required": true,
      "constraints": [
        "maximum length: 4096"
      ]
    },
    {
      "name": "project_id",
      "type": "string",
      "description": "Project ID from the request, if applicable.",
      "constraints": [
        "maximum length: 512"
      ]
    },
    {
      "name": "typed_rpc",
      "type": "bool",
      "description": "Whether the request used a typed RPC (true) or the generic proxy (false)."
    },
    {
      "name": "rpc_method",
      "type": "string",
      "description": "RPC method name (e.g., \"GetProject\", \"Proxy\").",
      "constraints": [
        "maximum length: 128"
      ]
    },
    {
      "name": "upstream_status",
      "type": "int32",
