{
  "name": "BootstrapConfig",
  "package": "kernel",
  "description": "BootstrapConfig is the top-level configuration for a Kernel node.\n Kernel provides distributed state management with gRPC access\n and clustered storage. This configuration is read once at boot and is\n immutable for the lifetime of the process.\n\n The config oneof determines how the gRPC configuration (Config)\n is sourced: from a URL, or from a local file.\n Unlike BootstrapConfig, Config can be reloaded at any time.",
  "fields": [
    {
      "name": "cluster_name",
      "type": "string",
      "description": "cluster_name is the logical name for this cluster.\n All nodes in the same cluster must use the same name.",
      "required": true
    },
    {
      "name": "listener",
      "type": "message",
      "description": "listener is the gRPC bind address for the Kernel server. Default port 5000.",
      "required": true,
      "message": {
        "name": "Host",
        "package": "host",
        "description": "Host identifies a network endpoint by hostname/IP and port.\n The host field accepts either an FQDN or an IP address (v4/v6).",
        "fields": [
          {
            "name": "host",
            "type": "string",
            "description": "Hostname or IP address (e.g. \"api.example.com\" or \"10.0.0.1\").",
            "required": true,
            "constraints": [
              "must be a valid hostname or IP address"
            ]
          },
          {
            "name": "port",
            "type": "int32",
            "description": "Port number (1-65535).",
            "constraints": [
              "must be a valid network port (1-65535)"
            ]
          },
          {
            "name": "protocol",
            "type": "enum",
            "description": "Transport protocol. Default TCP (zero value).",
            "enum_values": [
              {
                "name": "TCP",
                "number": 0
              },
              {
                "name": "UDP",
                "number": 1
              }
            ]
          }
        ]
      }
    },
    {
      "name": "members",
      "type": "message (recursive reference: host.Host)",
      "description": "members is the list of cluster member addresses for discovery (e.g. host=10.0.0.1, port=9443).\n At least one member must be specified for the node to join the cluster.",
      "required": true,
      "repeated": true
    },
    {
      "name": "node_count",
      "type": "int32",
      "description": "node_count is the expected number of nodes in the cluster.\n Used for partition planning and quorum calculations.\n Must be at least 1.",
      "constraints": [
        "must be \u003e 0"
      ]
    },
    {
      "name": "partition_count",
      "type": "int32",
      "description": "partition_count is the number of partitions to distribute data across.\n More partitions enable finer-grained distribution but increase metadata overhead.\n Default: 271 (prime number for better distribution).\n Must be greater than 0.",
      "default": 271,
      "constraints": [
        "must be \u003e 0"
      ]
    },
    {
      "name": "network",
      "type": "message",
      "description": "network configures cluster networking (timeouts, heartbeats, etc.).",
      "required": true,
      "message": {
        "name": "NetworkConfig",
        "package": "hazelcast",
        "description": "NetworkConfig configures cluster networking behavior.",
        "fields": [
          {
            "name": "connect_timeout_seconds",
            "type": "int64",
            "description": "connect_timeout_seconds is the maximum time to wait when connecting to a cluster member.\n Default: 5 seconds.",
            "default": 5,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ]
          },
          {
            "name": "heartbeat_interval_seconds",
            "type": "int64",
            "description": "heartbeat_interval_seconds is the interval between heartbeat messages sent to cluster members.\n Used to detect failed nodes.",
            "default": 5,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ]
          },
          {
            "name": "heartbeat_timeout_seconds",
            "type": "int64",
            "description": "heartbeat_timeout_seconds is the time after which a member is considered unreachable\n if no heartbeat is received. Must be greater than heartbeat_interval_seconds.",
            "default": 60,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ]
          }
        ]
      }
    },
    {
      "name": "logger",
      "type": "message",
      "description": "logger configures logging for the Kernel server.",
      "required": true,
      "message": {
        "name": "LoggerConfig",
        "package": "logger",
        "description": "LoggerConfig represents the configuration for a logger instance.\n It controls the output format, verbosity level, and formatting options.\n\n Example usage:\n   - Development mode with console output and pretty printing for local debugging\n   - Production mode with JSON output and no pretty printing for log aggregation",
        "fields": [
          {
            "name": "name",
            "type": "string",
            "description": "Name is the logger name/component identifier",
            "constraints": [
              "maximum length: 128"
            ]
          },
          {
            "name": "format",
            "type": "enum",
            "description": "Format determines the output format for log messages (JSON or console)\n Default: FORMAT_JSON in production, FORMAT_CONSOLE in development",
            "enum_values": [
              {
                "name": "FORMAT_JSON",
                "number": 1,
                "description": "FORMAT_JSON outputs logs as JSON objects, ideal for structured logging and log aggregation systems"
              },
              {
                "name": "FORMAT_CONSOLE",
                "number": 2,
                "description": "FORMAT_CONSOLE outputs logs in a human-readable console format, ideal for development and debugging"
              }
            ]
          },
          {
            "name": "level",
            "type": "enum",
            "description": "Level sets the minimum severity level for log messages to be output\n Messages below this level will be filtered out\n Default: LEVEL_INFO in production, LEVEL_DEBUG in development",
            "enum_values": [
              {
                "name": "LEVEL_TRACE",
                "number": 1,
                "description": "LEVEL_TRACE is the most verbose log level, used for detailed debugging information"
              },
              {
                "name": "LEVEL_DEBUG",
                "number": 2,
                "description": "LEVEL_DEBUG is used for debugging information, less verbose than trace"
              },
              {
                "name": "LEVEL_INFO",
                "number": 3,
                "description": "LEVEL_INFO is used for informational messages about normal operations"
              },
              {
                "name": "LEVEL_WARN",
                "number": 4,
                "description": "LEVEL_WARN is used for warning messages about potentially problematic situations"
              },
              {
                "name": "LEVEL_ERROR",
                "number": 5,
                "description": "LEVEL_ERROR is used for error messages about failures and problems"
              }
            ]
          },
          {
            "name": "development",
            "type": "bool",
            "description": "Development enables development mode which:\n   - Uses console format by default\n   - Enables stack traces for warnings and errors\n   - Uses more human-readable timestamps\n Default: false (production mode)"
          },
          {
            "name": "pretty_print",
            "type": "bool",
            "description": "PrettyPrint enables pretty-printed output for JSON format\n This makes JSON logs more readable but increases output size\n Should be disabled in production for performance\n Default: false"
          },
          {
            "name": "output_paths",
            "type": "string",
            "description": "OutputPaths is a list of file paths or URLs to write logs to\n Use \"stdout\" or \"stderr\" for console output\n Example: [\"stdout\", \"/var/log/app.log\"]",
            "repeated": true,
            "constraints": [
              "must be a valid file path (type: PATH_ANY)"
            ]
          },
          {
            "name": "error_output_paths",
            "type": "string",
            "description": "ErrorOutputPaths is a list of file paths or URLs to write error logs to\n Use \"stderr\" for console error output\n Example: [\"stderr\", \"/var/log/app-errors.log\"]",
            "repeated": true,
            "constraints": [
              "must be a valid file path (type: PATH_ANY)"
            ]
          },
          {
            "name": "disable_caller",
            "type": "bool",
            "description": "DisableCaller disables automatic inclusion of caller information (file:line) in log entries\n Default: false (caller information is included)"
          },
          {
            "name": "disable_stacktrace",
            "type": "bool",
            "description": "DisableStacktrace disables automatic stacktraces for error-level and above log entries\n Default: false (stacktraces are included for errors)"
          },
          {
            "name": "initial_fields",
            "type": "map",
            "description": "InitialFields is a map of fields to include in every log entry\n Useful for adding context like service name, version, environment, etc.\n Example: {\"service\": \"api\", \"version\": \"1.0.0\", \"environment\": \"production\"}",
            "repeated": true,
            "map_key_type": "string",
            "map_value_type": "string"
          }
        ]
      }
    },
    {
      "name": "persistence_dir",
      "type": "string",
      "description": "persistence_dir is the directory where DB dumps and redo logs are stored.\n Default: \"data/kernel\".",
      "default": "data/kernel"
    },
    {
      "name": "persistence_format",
      "type": "enum",
      "description": "persistence_format configures the serialization format for redo logs and dumps.\n Default: OUTPUT_FORMAT_PROTO_WIRE (binary protobuf).",
      "enum_values": [
        {
          "name": "OUTPUT_FORMAT_JSON",
          "number": 1,
          "description": "JSON format"
        },
        {
          "name": "OUTPUT_FORMAT_YAML",
          "number": 2,
          "description": "YAML format"
        },
        {
          "name": "OUTPUT_FORMAT_MULTI_YAML",
          "number": 3,
          "description": "Multi YAML format (e.g. ---)"
        },
        {
          "name": "OUTPUT_FORMAT_TEXT",
          "number": 4,
          "description": "Plain text format"
        },
        {
          "name": "OUTPUT_FORMAT_ENV_VAR",
          "number": 5,
          "description": "Environment variable format"
        },
        {
          "name": "OUTPUT_FORMAT_PROTO_WIRE",
          "number": 6,
          "description": "Protobuf wire format (binary)"
        },
        {
          "name": "OUTPUT_FORMAT_TOML",
          "number": 7,
          "description": "TOML format"
        }
      ]
    },
    {
      "name": "url_loader",
      "type": "message",
      "description": "url_loader fetches the config from a URL (HTTPS with optional auth token).",
      "message": {
        "name": "UrlLoader",
        "package": "kernel",
        "description": "UrlLoader fetches gRPC configuration from a URL.\n Supports HTTPS with optional bearer token authentication.\n TLS verification uses BootstrapConfig.loader_ca.",
        "fields": [
          {
            "name": "url",
            "type": "string",
            "description": "url is the HTTPS URL to fetch the configuration from.",
            "required": true
          },
          {
            "name": "token",
            "type": "string",
            "description": "token is the bearer token for authentication.\n Sent as \"Authorization: Bearer \u003ctoken\u003e\" header."
          }
        ]
      }
    },
    {
      "name": "file_loader",
      "type": "message",
      "description": "file_loader loads the config from a local file on disk.",
      "message": {
        "name": "FileLoader",
        "package": "kernel",
        "description": "FileLoader loads gRPC configuration from a local file on disk.",
        "fields": [
          {
            "name": "path",
            "type": "string",
            "description": "path is the filesystem path to the configuration file.",
            "required": true
          }
        ]
      }
    },
    {
      "name": "loader_ca",
      "type": "message",
      "description": "loader_ca is the CA certificate trusted for TLS verification when\n fetching Config via url_loader.",
      "repeated": true,
      "message": {
        "name": "X509Cert",
        "package": "x509",
        "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
        "fields": [
          {
            "name": "id",
            "type": "string",
            "description": "Id is a unique identifier for the certificate"
          },
          {
            "name": "base64",
            "type": "string",
            "description": "Base64 contains the base64url-encoded PEM certificate block",
            "required": true,
            "constraints": [
              "must be base64 encoded"
            ]
          }
        ]
      }
    },
    {
      "name": "tls",
      "type": "message",
      "description": "tls is the node's X.509 certificate and private key, used for\n gRPC server TLS and Hazelcast mTLS.",
      "required": true,
      "message": {
        "name": "X509CertChain",
        "package": "x509",
        "description": "X509CertChain contains a certificate chain and optional private key.\n chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.\n When key is present, the chain is a full credential suitable for TLS.",
        "fields": [
          {
            "name": "chain",
            "type": "message (recursive reference: x509.X509Cert)",
            "description": "chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.",
            "repeated": true
          },
          {
            "name": "key",
            "type": "message",
            "description": "optional private key for the leaf cert; present when chain is a full credential.",
            "message": {
              "name": "Key",
              "package": "key",
              "description": "Key represents a private cryptographic key (alias for ProtoKey).",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the key (corresponds to kid in JWK)",
                  "required": true,
                  "constraints": [
                    "minimum length: 1"
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM private key block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded",
                    "encoding type: ENC_TYPE_KEY_PRIVATE_ANY"
                  ]
                },
                {
                  "name": "created",
                  "type": "int64",
                  "description": "Created is the Unix epoch timestamp (seconds) when the key was created\n Valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                  "required": true,
                  "constraints": [
                    "must be \u003e= 1735689600",
                    "must be \u003c= 8045740800"
                  ]
                }
              ]
            }
          }
        ]
      }
    },
    {
      "name": "hazelcast_listener",
      "type": "message (recursive reference: host.Host)",
      "description": "hazelcast_listener is the bind address for Hazelcast cluster communication. Default port 5001."
    }
  ]
}

