{
  "name": "Config",
  "package": "kernel",
  "description": "Config is the gRPC configuration for Kernel.\n Unlike BootstrapConfig (read once at boot), Config can be reloaded at any time.",
  "fields": [
    {
      "name": "trusted_cas",
      "type": "message",
      "description": "trusted_cas lists the trusted CA certificates for TLS verification.",
      "repeated": true,
      "message": {
        "name": "X509Cert",
        "package": "x509",
        "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
        "fields": [
          {
            "name": "id",
            "type": "string",
            "description": "Id is a unique identifier for the certificate"
          },
          {
            "name": "base64",
            "type": "string",
            "description": "Base64 contains the base64url-encoded PEM certificate block",
            "required": true,
            "constraints": [
              "must be base64 encoded"
            ]
          }
        ]
      }
    },
    {
      "name": "rate_limit",
      "type": "message",
      "description": "rate_limit configures rate limiting for unary read RPCs to detect polling.",
      "required": true,
      "message": {
        "name": "RateLimitConfig",
        "package": "hazelcast",
        "description": "RateLimitConfig configures rate limiting for unary read RPCs to detect polling.\n Two categories are tracked independently:\n - polling_rate: unary RPCs that have streaming alternatives (Watch/Subscribe)\n - unary_rate: unary read RPCs without streaming alternatives",
        "fields": [
          {
            "name": "polling_rate",
            "type": "double",
            "description": "Max req/s per peer per method for unary RPCs that have streaming alternatives.",
            "default": 2
          },
          {
            "name": "unary_rate",
            "type": "double",
            "description": "Max req/s per peer per method for unary read RPCs without streaming alternatives.",
            "default": 10
          }
        ]
      }
    },
    {
      "name": "configs",
      "type": "message",
      "description": "configs holds per-service configurations. On each config load,\n each entry is written to the corresponding service config state boundary.",
      "required": true,
      "message": {
        "name": "Services",
        "package": "services_config",
        "fields": [
          {
            "name": "sentinel_config",
            "type": "message",
            "message": {
              "name": "Config",
              "package": "sentinel",
              "fields": []
            }
          },
          {
            "name": "oauth_config",
            "type": "message",
            "message": {
              "name": "Config",
              "package": "oauth",
              "fields": [
                {
                  "name": "enable",
                  "type": "bool",
                  "description": "enable enables or disables OAuth2 authentication."
                },
                {
                  "name": "scopes",
                  "type": "string",
                  "description": "scopes are the default OAuth2 scopes requested from all providers.\n If empty, defaults to [\"openid\", \"profile\", \"email\"].",
                  "repeated": true
                },
                {
                  "name": "providers",
                  "type": "message",
                  "description": "providers is the list of OAuth2 identity provider configurations.",
                  "repeated": true,
                  "message": {
                    "name": "ProviderConfig",
                    "package": "oauth",
                    "description": "ProviderConfig configures a single OAuth2 identity provider.",
                    "fields": [
                      {
                        "name": "enable",
                        "type": "bool",
                        "description": "enable enables or disables this provider."
                      },
                      {
                        "name": "name",
                        "type": "string",
                        "description": "name is a human-friendly label (e.g. \"Google\", \"Okta\", \"Microsoft\").",
                        "constraints": [
                          "minimum length: 1"
                        ]
                      },
                      {
                        "name": "domains",
                        "type": "string",
                        "description": "domains maps email domains to this provider. When a user's email domain\n matches, they are routed to this IDP automatically.",
                        "repeated": true
                      },
                      {
                        "name": "issuer",
                        "type": "string",
                        "description": "issuer is the OpenID Connect issuer URL.\n Used for .well-known/openid-configuration auto-discovery.",
                        "required": true,
                        "constraints": [
                          "must be a valid URL (scheme: URL_SCHEME_HTTPS)"
                        ]
                      },
                      {
                        "name": "client_id",
                        "type": "string",
                        "description": "client_id is the OAuth2 client identifier.",
                        "required": true,
                        "constraints": [
                          "minimum length: 1"
                        ]
                      },
                      {
                        "name": "client_secret",
                        "type": "string",
                        "description": "client_secret is the OAuth2 client secret.",
                        "required": true,
                        "constraints": [
                          "minimum length: 1"
                        ]
                      },
                      {
                        "name": "authorization_endpoint",
                        "type": "string",
                        "description": "authorization_endpoint overrides the auto-discovered authorization URL.",
                        "constraints": [
                          "must be a valid URL (scheme: URL_SCHEME_HTTPS)"
                        ]
                      },
                      {
                        "name": "token_endpoint",
                        "type": "string",
                        "description": "token_endpoint overrides the auto-discovered token URL.",
                        "constraints": [
                          "must be a valid URL (scheme: URL_SCHEME_HTTPS)"
                        ]
                      },
                      {
                        "name": "end_session_endpoint",
                        "type": "string",
                        "description": "end_session_endpoint overrides the auto-discovered logout URL.",
                        "constraints": [
                          "must be a valid URL (scheme: URL_SCHEME_HTTPS)"
                        ]
                      },
                      {
                        "name": "scopes",
                        "type": "string",
                        "description": "scopes overrides the default scopes for this provider.",
                        "repeated": true
                      }
                    ]
                  }
                },
                {
                  "name": "nonce_expire_seconds",
                  "type": "int64",
                  "description": "nonce_expire_seconds is how long OAuth2 nonces/state remain valid.\n Nonces prevent replay attacks in the authorization code flow.\n Minimum: 1 second. Maximum: 86400 (24 hours). Default: 300 (5 minutes).",
                  "default": 300,
                  "constraints": [
                    "duration constraint: DURATION_TYPE_POSITIVE",
                    "minimum value: 1",
                    "maximum value: 86400"
                  ]
                },
                {
                  "name": "jwk_refetch_interval_seconds",
                  "type": "int64",
                  "description": "jwk_refetch_interval_seconds is the minimum interval between JWKS fetches\n from the same external IDP. Prevents excessive outbound requests.\n Default: 300 (5 minutes).",
                  "default": 300,
                  "constraints": [
                    "duration constraint: DURATION_TYPE_POSITIVE"
                  ]
                },
                {
                  "name": "profiles_policy",
                  "type": "message",
                  "description": "profiles_policy is the OPA policy for determining user entitlement profiles\n at token exchange time. Contains a filesystem.Directory bundle of .rego files.\n The policy's entry_point rule receives {claims: {\u003cIDP claims\u003e}} and must\n return {profiles: [string]}. Profile names are resolved to concrete\n entitlements via entitlement_profiles in kernel config.",
                  "message": {
                    "name": "OpaPolicy",
                    "package": "opa",
                    "description": "OpaPolicy defines an OPA policy bundle for authorization evaluation.\n The bundle is a filesystem.Directory tree containing .rego policy files.",
                    "fields": [
                      {
                        "name": "entry_point",
                        "type": "string",
                        "description": "entry_point specifies the main package/decision point for policy evaluation.",
                        "constraints": [
                          "maximum length: 256",
                          "minimum length: 1"
                        ]
                      },
                      {
                        "name": "bundle",
                        "type": "message",
                        "description": "bundle is the directory tree containing .rego policy files.",
                        "message": {
                          "name": "Directory",
                          "package": "filesystem",
                          "description": "Directory represents a directory node in a filesystem tree.\n Directories are recursive — each may contain child directories and files.",
                          "fields": [
