{
  "name": "Identity",
  "package": "kernel",
  "description": "Identity holds the public verifying keys for kernel's token exchange service.\n Kernel is the sole token authority — all tokens (S2S, U2S, refresh) and\n X.509 certificates are signed by kernel's keys.\n\n Token exchange handles:\n   1. Direct exchange: delegate presents cred_pair JWT or cloud proof → token/cert\n   2. Delegation: broker (OAuth, K8S) authenticates via header, mints on behalf\n\n Access: RW for kernel, RO for any service that needs to verify tokens.",
  "fields": [
    {
      "name": "verifying_keys",
      "type": "message",
      "description": "Verification keys — kernel's public keys, rotated periodically.\n Kernel holds the corresponding private keys internally.\n Used by SecurityInterceptor to validate tokens for cluster calls.",
      "repeated": true,
      "message": {
        "name": "Jwk",
        "package": "jwk",
        "description": "Jwk represents a JSON Web Key as defined in RFC 7517.\n It contains the public key parameters for RSA (e, n), EC (crv, x, y), or OKP (crv, x) keys.\n JWK is used for key distribution and verification in JSON-based protocols like JWT.",
        "fields": [
          {
            "name": "kty",
            "type": "enum",
            "description": "Kty is the key type parameter (RSA, EC, or OKP)",
            "enum_values": [
              {
                "name": "KEY_TYPE_RSA",
                "number": 1,
                "description": "KeyTypeRsa represents an RSA key type"
              },
              {
                "name": "KEY_TYPE_EC",
                "number": 2,
                "description": "KeyTypeEc represents an Elliptic Curve key type"
              },
              {
                "name": "KEY_TYPE_OKP",
                "number": 3,
                "description": "KeyTypeOkp represents an Octet Key Pair (EdDSA) key type"
              }
            ]
          },
          {
            "name": "alg",
            "type": "string",
            "description": "Alg is the algorithm intended for use with the key (e.g., \"RS384\", \"ES256\", \"EdDSA\")",
            "required": true,
            "constraints": [
              "minimum length: 1"
            ]
          },
          {
            "name": "kid",
            "type": "string",
            "description": "Kid is the key ID used to match keys with signatures",
            "required": true,
            "constraints": [
              "minimum length: 1"
            ]
          },
          {
            "name": "use",
            "type": "enum",
            "description": "Use indicates the intended use of the key (sig for signatures, enc for encryption)",
            "enum_values": [
              {
                "name": "JWK_USE_TYPE_SIG",
                "number": 1,
                "description": "JwkUseTypeSig indicates the key is used for digital signatures"
              },
              {
                "name": "JWK_USE_TYPE_ENC",
                "number": 2,
                "description": "JwkUseTypeEnc indicates the key is used for encryption"
              }
            ]
          },
          {
            "name": "e",
            "type": "string",
            "description": "E is the RSA public exponent (base64url encoded without padding)",
            "constraints": [
              "must be base64 encoded"
            ]
          },
          {
            "name": "n",
            "type": "string",
            "description": "N is the RSA modulus (base64url encoded without padding)",
            "constraints": [
              "must be base64 encoded"
            ]
          },
          {
            "name": "crv",
            "type": "string",
            "description": "Crv is the elliptic curve name (e.g., P-256, P-384, P-521, Ed25519)"
          },
          {
            "name": "x",
            "type": "string",
            "description": "X is the x coordinate for EC keys or the public key for OKP (base64url encoded without padding)",
            "constraints": [
              "must be base64 encoded"
            ]
          },
          {
            "name": "y",
            "type": "string",
            "description": "Y is the y coordinate for EC keys (base64url encoded without padding, not used for OKP)",
            "constraints": [
              "must be base64 encoded"
            ]
          },
          {
            "name": "exp",
            "type": "int64",
            "description": "Exp is the expiration in epoch seconds. This is not part of the JWK spec as the spec does\n not specify how to handle public key expiration.\n When stored in a collection with epoch_expiration, Hazelcast computes TTL = exp - now\n and auto-evicts the entry on expiry."
          },
          {
            "name": "created",
            "type": "int64",
            "description": "Created is the Unix epoch timestamp (seconds) when the key was created (optional).\n If set, valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
            "constraints": [
              "must be \u003c= 8045740800",
              "must be \u003e= 1735689600"
            ]
          }
        ]
      }
    },
    {
      "name": "fqdn",
      "type": "message",
      "description": "fqdn is the cluster's public hostname, published from Config on\n each config load. Services (e.g. letsencrypt) watch this to discover\n the cluster FQDN without needing it in their own config.",
      "message": {
        "name": "IdentityFqdn",
        "package": "kernel",
        "description": "IdentityFqdn wraps the cluster's FQDN for publication as a singleton\n boundary in Identity state.",
        "fields": [
          {
            "name": "fqdn",
            "type": "string"
          }
        ]
      }
    }
  ]
}

